import '../utils/json_utils.dart';

/// `observationReports/{reportId}` — a short, plain-language note for the
/// teacher, generated by Gemini from a student's session data over a date range.
class ObservationReport {
  const ObservationReport({
    required this.id,
    required this.studentId,
    required this.generatedText,
    required this.rangeStart,
    required this.rangeEnd,
    required this.createdBy,
    required this.timestamp,
    this.basedOnSessionIds = const [],
  });

  final String id;
  final String studentId;
  final String generatedText;
  final List<String> basedOnSessionIds;
  final DateTime rangeStart;
  final DateTime rangeEnd;

  /// uid of the teacher who generated it.
  final String createdBy;
  final DateTime timestamp;

  Map<String, dynamic> toJson() => {
    'id': id,
    'studentId': studentId,
    'generatedText': generatedText,
    'basedOnSessionIds': basedOnSessionIds,
    'rangeStart': dateTimeToJson(rangeStart),
    'rangeEnd': dateTimeToJson(rangeEnd),
    'createdBy': createdBy,
    'timestamp': dateTimeToJson(timestamp),
  };

  factory ObservationReport.fromJson(Map<String, dynamic> json) =>
      ObservationReport(
        id: (json['id'] as String?) ?? '',
        studentId: (json['studentId'] as String?) ?? '',
        generatedText: (json['generatedText'] as String?) ?? '',
        basedOnSessionIds: stringListFromJson(json['basedOnSessionIds']),
        rangeStart: dateTimeFromJson(json['rangeStart']),
        rangeEnd: dateTimeFromJson(json['rangeEnd']),
        createdBy: (json['createdBy'] as String?) ?? '',
        timestamp: dateTimeFromJson(json['timestamp']),
      );
}
